import{z as s,x as B,o as E,c as A,q as t,j as r,D as e,d as i,s as o,S as l}from"./chunks/framework.C8m1ZpeB.js";const g=JSON.parse('{"title":"领导者选举与脑裂","description":"","frontmatter":{"title":"领导者选举与脑裂","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/leader-election-split-brain.md","filePath":"cs/leader-election-split-brain.md","lastUpdated":1791063341000}'),p={name:"cs/leader-election-split-brain.md"};function d(c,a,f,_,m,h){const n=B("Mermaid");return E(),A("div",null,[a[2]||(a[2]=t('<h1 id="领导者选举与脑裂" tabindex="-1">领导者选举与脑裂 <a class="header-anchor" href="#领导者选举与脑裂" aria-label="Permalink to &quot;领导者选举与脑裂&quot;">​</a></h1><div class="epigraph"><p>分区两侧各选一个主，就是脑裂。心跳选主只解决活，fencing 与多数派才解决「至多一个有效主」。</p><footer>—— 据 Lamport Paxos / Ongaro Raft 的任期规则；Gray and Cheriton 租约整理</footer></div><p>上一课<a href="/cs/consensus-vs-2pc">共识与 2PC</a>指出单协调者会堵。人们于是「选个新协调者」。缺口是<strong>两侧同时成功</strong>：那不是高可用，是分叉写。<a href="/cs/primary-backup-failover">主备</a>已点过 fencing，本课把选举算法与脑裂收成一条课，不重写 Raft 日志匹配。后课锁服务是选举结果的用户。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>选举规格常被写成：终有一个主（活性）、至多一个主（安全）。<a href="/cs/flp-impossibility">FLP</a>说异步确定下二者不能兼得。工程选举：Bully（最高 id）、Raft 投票、ZK 临时节点。只比谁超时谁当选，在分区下<strong>两侧都当选</strong>。</p><p>脑裂定义：两个节点同时认为自己持有同一互斥角色，且客户端或存储都接受双方的写。安全破坏是分叉，不是「切换慢」。</p><p><span class="marginnote">直觉类比：脑裂像一家公司同时冒出两个「总经理」——各自签字、公章都有效（存储与客户端都收），档案里出现两套互相矛盾的真相。它不是「交接期间没人管」，而是「两个人都在管且都管成了」。</span></p><p><span class="marginnote">多数派选举：同一任期只有一个能拿到多数票，因为票不相交。少数派分区选不出。这是 CP。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>防脑裂三件套（可组合）：</p><ol><li>多数派投票 / 共识任期。</li><li>租约：旧主期限未到新主不接写。</li><li>存储 fencing token：IO 带单调令牌，存储拒旧令牌。</li></ol>',11)),(E(),r(l,null,{default:e(()=>[o(n,{id:"mermaid-45",class:"mermaid",graph:"flowchart%20TD%0A%20%20PART%5B%22%E5%88%86%E5%8C%BA%22%5D%20--%3E%20TWO%5B%22%E4%B8%A4%E4%BE%A7%E5%90%84%E8%87%AA%E9%80%89%E4%B8%BB%22%5D%0A%20%20TWO%20--%3E%20SPLIT%5B%22%E8%84%91%E8%A3%82%E5%86%99%22%5D%0A%20%20MAJ%5B%22%E5%A4%9A%E6%95%B0%E6%B4%BE%22%5D%20--%3E%20ONE%5B%22%E8%87%B3%E5%A4%9A%E4%B8%80%E4%BE%A7%E9%80%89%E5%87%BA%22%5D%0A%20%20FENCE%5B%22fencing%20token%22%5D%20--%3E%20REJ%5B%22%E5%AD%98%E5%82%A8%E6%8B%92%E6%97%A7%E4%B8%BB%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<p>不要用「再加一层心跳」当 3 的替代：心跳过不了分区。</p><p><span class="marginnote">常见误区：初学者以为「心跳超时就该自动切主」很安全。心跳只能告诉一侧「我联系不上你」，它<strong>取消不了</strong>另一侧：分区对面的旧主没收到任何通知，还在照常收写。让旧主作废的从来不是心跳，而是它写不进多数派、或存储拒了它的旧令牌。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>Raft：term 单调，AppendEntries 拒小 term；多数派保证同 term 一主。旧主在分区里仍自认主，但它的写凑不齐多数派，不能提交——若它<strong>对外部存储</strong>直写绕过日志，仍会脑裂。所以角色必须覆盖所有副作用路径。</p><p>ZK/etcd 选主：临时节点最小者当主，会话超时后节点消失。会话超时依赖<a href="/cs/leases">租约</a>算术；超时设太短会误杀，太长则 failover 慢。误杀加没 fencing 的副作用 = 脑裂。</p><p>本课不把 DNS 主备切换当多数派。也不写区块链的最长链（后课 PoW 是另一种「谁说了算」）。</p><p><span class="marginnote">数字实例：5 节点集群分区成 3+2。多数侧手握 3 票 \\(\\gt \\frac{5}{2}\\)，能继续选出主并提交；少数侧无论怎么投都凑不齐 3 票，选出的「主」写不进日志。推而广之，\\(2f+1\\) 个节点容 \\(f\\) 台故障——每多容一台故障，就要多买两台来保住「票不相交」的算术。</span></p>',7)),(E(),r(l,null,{default:e(()=>[o(n,{id:"mermaid-67",class:"mermaid",graph:"flowchart%20TD%0A%20%20OLD%5B%22%E6%97%A7%E4%B8%BB%E6%8C%81%20fencing%20token%3D34%2C%20%E9%81%87%E9%95%BF%20GC%20%E5%8D%A1%E9%A1%BF%22%5D%20--%3E%20LEASE%5B%22%E7%A7%9F%E7%BA%A6%E5%88%B0%E6%9C%9F%2C%20%E9%9B%86%E7%BE%A4%E9%80%89%E5%87%BA%E6%96%B0%E4%B8%BB%22%5D%0A%20%20LEASE%20--%3E%20NEW%5B%22%E6%96%B0%E4%B8%BB%E9%A2%86%20token%3D35%2C%20%E5%BC%80%E5%A7%8B%E6%AD%A3%E5%B8%B8%E5%86%99%E5%AD%98%E5%82%A8%22%5D%0A%20%20OLD%20--%3E%7C%22%E5%8D%A1%E9%A1%BF%E8%8B%8F%E9%86%92%2C%20%E4%BB%A5%E4%B8%BA%E8%87%AA%E5%B7%B1%E8%BF%98%E6%98%AF%E4%B8%BB%22%7C%20W%5B%22%E5%90%91%E5%AD%98%E5%82%A8%E5%8F%91%E5%86%99%E8%AF%B7%E6%B1%82%2C%20%E5%B8%A6%20token%3D34%22%5D%0A%20%20W%20--%3E%20CHK%5B%22%E5%AD%98%E5%82%A8%E6%AF%94%E8%BE%83%3A%2034%20%5Clt%2035%2C%20%E6%8B%92%E7%BB%9D%22%5D%0A%20%20NEW%20--%3E%20OK%5B%22token%3D35%20%E7%9A%84%E5%86%99%E5%85%A5%E8%A2%AB%E6%8E%A5%E5%8F%97%2C%20%E6%97%A0%E5%88%86%E5%8F%89%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<p>这张图回答的问题：fencing token 具体在哪个环节挡住旧主。关键画在存储那一比——令牌单调，旧主的写带着更小的号码到场，存储一比就拒。多数派保证「至多一个能提交」，存储令牌保证「至多一个能写盘」，两者合起来旧主复活也翻不了盘。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不比较所有选主库的 API。不引入拜占庭多主。后课默认：宣布领导者必须有 fencing 故事；多数派选举给「至多一个能提交」，租约给「至多一个能被客户端信」，存储令牌给「至多一个能写盘」。分布式锁下一课把令牌变成锁服务产品。</p><p>活性要分区愈合；安全要在分区期间仍「至多一个有效主」。有效 = 其写被系统接受。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>脑裂是两主的写都被接受，不是切换慢。</li><li>多数派选举让少数派选不出；还要对副作用 fencing。</li><li>心跳不能穿过分区去取消另一侧的主。</li><li>出处：Raft/Paxos 任期；Gray–Cheriton 租约。</li></ul>',6))])}const C=s(p,[["render",d]]);export{g as __pageData,C as default};
